# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
G=[['希腊 legein／lego（λέγειν／λέγω）','说、讲；与“挑选、收集”的更早词族有关']]
X=G+[['希腊 lexis（λέξις）；lexikos（λεξικός）','说法、词语；与词语有关的']]
LX=X+[['希腊 lexikon，省略了“书”一词','词语之书、词书'],['新拉丁 lexicon；经法语或直接进入英语 lexicon','词典；一个领域、语言或人的词汇库']]
LC=X+[['拉丁化的 lexic- + -al → 英语 lexical','与词汇有关的']]
def H(chain,label,meaning):return chain+[[label,meaning]]
WA=[
E('lexicon','英 /ˈleksɪkən/，亦 /ˈleksɪkɒn/；美 /ˈleksɪkɑːn/','词汇库；词汇；词典〔尤指古典语言词典〕','把某个人、某个领域会用的词，想成一整个装词的柜子。','希腊 lexikon 原为“词语的”，省略后面的 biblion“书”，后来本身就表示词书；再经新拉丁语、法语等进入英语。',LX,'a Greek lexicon 可以是一本希腊语词典；the lexicon of medicine 是医学领域的词汇。enter the lexicon 则说一个表达逐渐进入大家会用的词汇库。这里的“柜子”是理解词汇集合的比喻，不是它的字面词源。','a mental lexicon；the lexicon of a field；enter the public lexicon。','dictionary 常指具体编成的词典；lexicon 还可指没有装订成书的词汇系统或个人词汇库。',('The term has entered the everyday lexicon.','这个术语已经进入日常词汇。'),('She checked the passage in a Greek lexicon.','她借助一本希腊语词典查读了那段文字。'),sources=['https://www.etymonline.com/word/lexicon','https://en.wiktionary.org/wiki/lexicon']),
E('lexis','/ˈleksɪs/','词汇；词语与常用组合〔语言学、教学〕','先不看句子的骨架，看看里面实际用了哪些词和常见搭配。','借用希腊 lexis“说话、表达、词语”，属于 legein“说”的词族。',H(X,'英语 lexis','词语、常用组合等词汇内容'),'英语教学里 lexis 可以包括单词，也包括经常作为整体学习的组合，如 make a decision。study lexis 就是关注语言拿哪些词块表达意思，不只是机械背一列孤立单词。','grammar and lexis；the lexis of a text；teach lexis in context。','lexis 常谈词汇内容；syntax 谈这些成分怎样组合成句子。两方面相互配合。',('The lesson focuses on the lexis of travel.','这节课重点学习旅行相关词汇。'),('Her analysis covers both grammar and lexis.','她的分析兼顾语法与词汇。'),sources=['https://en.wiktionary.org/wiki/lexis','https://www.collinsdictionary.com/dictionary/english/lexis']),
E('lexical','/ˈleksɪkəl/','词汇的；与词语有关的','把放大镜对准“用了什么词”，而不是只看句子的排列方式。','来自希腊 lexikos“词语的”的拉丁化词干，再接 -al；并不是英语 lexis 随便插一个 c。',LC,'a lexical choice 是选哪个词；lexical meaning 是词所承载的意义。语言学中 lexical word 常指名词、动词等有较丰富实义的词，与承担语法作用的 function word 对照；具体划分要看理论。','lexical meaning；lexical choice；lexical knowledge；lexical analysis。','lexical 问词语本身，grammatical 问语法形式或规则；一个句子可能词选对了，语法仍有问题。',('The two versions differ mainly in lexical choice.','两个版本主要在用词上不同。'),('The test measures learners’ lexical knowledge.','测试衡量学习者的词汇知识。'),sources=['https://www.etymonline.com/word/lexical','https://en.wiktionary.org/wiki/lexical']),
E('lexically','/ˈleksɪkli/','从词汇上看；在词汇层面','先把句式放一边，只比较词语的选择和词义。','lexical + -ly，常规形成 -ically 的副词形式。',H(LC,'英语 lexical → lexically','词汇的 → 从词汇角度'),'两种说法 lexically similar，是说它们使用的词或词汇关系相近，不保证句法结构也一样。某个意义 lexically expressed，则是通过词语本身表达，而非只靠语法安排表达。','lexically related；lexically distinct；lexically expressed。','lexically 是词汇层面；phonetically 是语音层面。听起来像，不一定在词义或词汇来源上相关。',('The passages are lexically similar but structurally different.','两段文字用词相近，结构却不同。'),('The distinction is expressed lexically in this language.','这种区别在这门语言中通过词汇来表达。'),sources=['https://www.collinsdictionary.com/dictionary/english/lexically','https://www.etymonline.com/word/lexical']),
E('lexeme','/ˈleksiːm/','词位〔一个词及其语法变化形式的抽象单位〕','把 run、runs、ran、running 看作同一家人的不同外套，底下共同的词汇身份就是 RUN。','近代以 lex- 词汇材料接 -eme，仿照语言学中表示基本单位的术语构词；不是古希腊现成整词直接借入。',X+[['近代 lex- + -eme → 英语 lexeme','词汇材料 + 基本单位 → 词位']],'词位是区分“同一个词的不同形式”与“另一个词”的工具。walk 和 walked 通常属于同一词位，walker 则通常是另一词位。不同学科也有专门用法：计算机词法分析中的 lexeme 常指实际匹配到的字符序列。','a single lexeme；forms of a lexeme；the lexeme RUN。','word form 是具体写出来或说出来的形式；lexeme 是把有关语法形式归在一起的词汇单位。',('“Walk” and “walked” are forms of the same lexeme.','walk 和 walked 是同一词位的不同形式。'),('The dictionary groups these forms under one lexeme.','词典把这些形式归在同一个词位下。'),sources=['https://en.wiktionary.org/wiki/lexeme','https://www.etymonline.com/word/lexeme','https://glossary.sil.org/term/lexeme']),
E('lexicalize','/ˈleksɪkəlaɪz/','使词汇化；用一个词汇单位表达','原来需要临时拼一串话，现在大家把它当成一个现成的表达来用。','lexical + -ize“使成为”；与 lexicalization 是对应的近代术语形式。',H(LC,'英语 lexical + -ize → lexicalize','与词汇有关的 → 使成为词汇单位、用词汇表达'),'一种语言可以 lexicalize 某个区别：为它准备专门的词。一个常用组合也可能逐渐被当作固定词汇单位理解。词汇化不要求一定去掉空格；关键是它是否成为约定俗成、整体调用的表达。','lexicalize a distinction；a lexicalized expression；become lexicalized。','lexicalize 关注是否变成词汇单位；spell as one word 只说写成一个单词，不能用空格数量替代语言分析。',('Different languages lexicalize different distinctions.','不同语言会用专门词汇表达不同的区别。'),('The phrase gradually became lexicalized.','这个短语逐渐成为一个固定词汇单位。'),sources=['https://www.merriam-webster.com/dictionary/lexicalize','https://en.wiktionary.org/wiki/lexicalize']),
E('lexicalization','英 /ˌleksɪkəlaɪˈzeɪʃən/；美 /ˌleksɪkələˈzeɪʃən/','词汇化','一个临时组合慢慢固定下来，使用者不再每次都从头拼装理解。','lexical 与 -ization 组成过程名词；与 lexicalize 对应，不仅指“被词典收录”。',H(LC,'英语 lexical + -ization → lexicalization','词汇层面的性质 → 形成词汇单位或用词汇编码意义的过程'),'词汇化可说某个意义由一个词承载，也可说原来透明的组合逐渐固定成惯用表达。词典通常在观察到这种使用后才收录；收录是记录行为，不是词汇化发生的唯一开关。','the process of lexicalization；lexicalization patterns；a case of lexicalization。','lexicalization 让表达成为词汇单位；grammaticalization 关注形式怎样发展出语法功能，两种过程的研究重点不同。',('The article traces the lexicalization of a common phrase.','文章追踪了一个常见短语的词汇化过程。'),('Dictionary inclusion may follow lexicalization rather than cause it.','词典收录可能发生在词汇化之后，而不是造成词汇化。'),sources=['https://www.merriam-webster.com/dictionary/lexicalization','https://en.wiktionary.org/wiki/lexicalization']),
E('lexicography','英 /ˌleksɪˈkɒɡrəfi/；美 /ˌleksɪˈkɑːɡrəfi/','词典编纂；词典学','研究真实用法，再决定词典里怎样收词、分义、写释义和选例句。','lexico-“词汇、词典” + -graphy“书写、记录”，属于近代学术构词。',X+[['近代 lexico- + -graphy → 英语 lexicography','词汇、词典 + 编写 → 词典编纂与其研究']],'lexicography 不是把单词按字母顺序放好就完成了。编辑要判断哪些义项有证据、释义是否好懂、例句能否展示实际用法。它既可以指编词典的实践，也可以指研究如何把词典做好的学术领域。','practical lexicography；historical lexicography；work in lexicography。','lexicography 以词典编纂及相关理论为中心；lexicology 研究词汇本身的结构、意义和关系，范围与任务不同。',('Corpus evidence has changed modern lexicography.','语料证据改变了现代词典编纂。'),('She studies lexicography and dictionary design.','她研究词典学与词典设计。'),sources=['https://www.etymonline.com/word/lexicography','https://www.merriam-webster.com/dictionary/lexicography']),
E('lexicographer','英 /ˌleksɪˈkɒɡrəfə/；美 /ˌleksɪˈkɑːɡrəfər/','词典编纂者','专门琢磨“这个词到底怎么用，怎样才能解释清楚”的人。','对应希腊 lexikon“词书”与 -graphos“写作者”的组合，英语形式可能受到法语 lexicographe 影响。',X+[['希腊 lexikon + -graphos → lexikographos 词族；经拉丁化、法语等形式','词书 + 写作者'],['英语 lexicographer','词典编纂者']],'lexicographer 既要查词，也要判断材料：一个新用法是偶然失误，还是已经被多人稳定使用？释义怎样写才不会用更难的词解释更简单的词？它是一种编辑和研究工作，不只是“记得很多单词的人”。','a dictionary lexicographer；work as a lexicographer；a team of lexicographers。','a lexicographer 编写、研究词典；a polyglot 会多种语言。两种身份可能重合，但并不等同。',('The lexicographer checked hundreds of examples before revising the entry.','词典编纂者查看了数百个用例，才修改这个词条。'),('A lexicographer must explain usage clearly.','词典编纂者必须把用法解释清楚。'),sources=['https://www.etymonline.com/word/lexicographer','https://www.collinsdictionary.com/dictionary/english/lexicographer']),
E('lexicographic','英 /ˌleksɪkəˈɡræfɪk/；美 /ˌleksɪkoʊˈɡræfɪk/','词典编纂的；字典序的','一种意思是站在编词典的角度；另一种是像查字典那样，逐位比较先后。','lexico-“词汇、词典”与 -graphic“记录、编写的”结合；与 lexicography 同族。',X+[['lexico- 与 -graphic 组合 → 英语 lexicographic','词典相关的；后来也说字典式排序的']],'lexicographic evidence 可以是编词典时使用的证据。计算机里的 lexicographic order 则按元素从前往后比较，先遇到不同处就决定顺序。例如把数字当字符串时，“10”会排在“2”前面，因为先比的是字符1和2。','lexicographic work；lexicographic order；lexicographic comparison。','lexicographic order 不等于数值大小排序；采用什么字符顺序，也要由具体比较规则规定。',('The project combines linguistic research with lexicographic work.','项目结合了语言研究与词典编纂工作。'),('In ordinary lexicographic order, “10” comes before “2.”','按通常的字符字典序，10 排在 2 前面。'),sources=['https://www.merriam-webster.com/dictionary/lexicographic','https://en.wiktionary.org/wiki/lexicographic','https://docs.python.org/3/reference/expressions.html#value-comparisons']),
E('lexicographical','英 /ˌleksɪkəˈɡræfɪkəl/；美 /ˌleksɪkoʊˈɡræfɪkəl/','词典编纂的；字典序的','仍是在说词典的编写或词典式的排列，只是用了较长的形容词形式。','与 lexicographic 同族的 -ical 形式；二者通常意义相近，不要凭长度制造等级差别。',X+[['lexico- 与 -graphical 组合 → 英语 lexicographical','与词典编写或字典序有关的']],'lexicographical research 是词典编纂研究；lexicographical order 是字典序。实际写作中 lexicographic 与 lexicographical 常能互换，选哪个往往取决于领域习惯和固定搭配，而不是一个专指理论、另一个专指实践。','lexicographical research；lexicographical order；lexicographical practice。','lexicographical 不是 geographical。前者围绕词汇和词典，后者围绕地理。',('The article examines nineteenth-century lexicographical practice.','文章考察了十九世纪的词典编纂实践。'),('The strings are listed in lexicographical order.','这些字符串按字典序列出。'),sources=['https://www.merriam-webster.com/dictionary/lexicographical','https://en.wiktionary.org/wiki/lexicographical','https://docs.python.org/3/reference/expressions.html#value-comparisons']),
E('lexicographically','英 /ˌleksɪkəˈɡræfɪkli/；美 /ˌleksɪkoʊˈɡræfɪkli/','按字典序；从词典编纂角度','先比第一个字符；相同再比第二个，一直找到能分出先后的地方。','lexicographical + -ly，对应按字典序或从词典编纂角度进行某事。',X+[['英语 lexicographical → lexicographically','字典序的、词典编纂的 → 按这种方式']],'sort names lexicographically 是按规定的字符比较顺序排序。大小写、重音字符和不同语言字母可能有不同排序约定，因此“字典序”并不自动给出全世界唯一顺序。词典研究语境中也可以译“从词典编纂角度”。','sort lexicographically；compare lexicographically；lexicographically smaller。','lexicographically 说比较办法；chronologically 说按时间先后。文件名按字典序排列，不保证日期也排对。',('The program sorts the labels lexicographically.','程序按字典序排列这些标签。'),('Compare the two strings lexicographically, starting at the left.','从左边开始，按字典序比较这两个字符串。'),sources=['https://www.merriam-webster.com/dictionary/lexicographically','https://en.wiktionary.org/wiki/lexicographically','https://docs.python.org/3/reference/expressions.html#value-comparisons']),
]
